local _, ns = ...
if ns.LOCALE ~= "frFR" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/frFR.lua.
L["WN49_1_TITLE"] = "Plus petit et plus léger"
L["WN49_1_TEXT"] = "Le téléchargement fait moins de la moitié de son ancienne taille et l'addon utilise moins de mémoire. Les thèmes teintent maintenant les dessins du jeu lui-même au lieu d'en inclure des copies, et un élément teinté par le thème n'est créé que la première fois qu'il s'affiche. Les thèmes gardent le même aspect."
L["WN49_2_TITLE"] = "Masquer le texte de zone"
L["WN49_2_TEXT"] = "Masque les noms de zone et de sous-zone qui apparaissent en fondu à l'écran quand vous entrez dans une région. Désactivé par défaut ; activez-le dans les options (/fcui), sous Autre."
L["WN49_3_TITLE"] = "Grimoire et barres"
L["WN49_3_TEXT"] = "Tant que le grimoire est ouvert, les barres latérales montrent leurs emplacements vides, comme dans Era, si bien qu'un sort peut y être placé directement, même en combat."
L["WN49_4_TITLE"] = "Onglets de la fenêtre du personnage"
L["WN49_4_TEXT"] = "Les onglets de la fenêtre du personnage sont ceux d'Era, comme sur Forever : à la taille de leur nom, avec l'onglet choisi ouvert sur la page."
L["WN49_5_TITLE"] = "Pages des options"
L["WN49_5_TEXT"] = "Les pages de la fenêtre des options sont regroupées par type : Apparence d'abord, puis les éléments à l'écran, les pages Minicarte et Carte côte à côte, puis les fenêtres du jeu, et Autre en dernier."
L["WN49_6_TITLE"] = "Corrections"
L["WN49_6_TEXT"] = "Les listes de caractéristiques et d'équipement de la fenêtre du personnage affichent de nouveau leurs flèches de défilement. Le portrait du grimoire remplit son anneau comme dans Era, celui du livre des métiers fait de même et ne grandit plus à l'ouverture, et l'icône de la fenêtre des collections n'est plus trop zoomée. La molette règle le zoom de l'aperçu des Apparences, et le gestionnaire de raid replié n'affiche plus de ligne en trop."
L["WN48_1_TITLE"] = "Carte et journal de quêtes réunis"
L["WN48_1_TEXT"] = "La liste des quêtes à côté de la carte, avec le texte et les récompenses de la quête choisie sur deux pages en dessous, comme la carte de Wrath. Tirez le coin de la carte pour la redimensionner et le séparateur pour élargir la liste. Désactivé par défaut ; activez Carte et quêtes classiques combinées dans les options (/fcui), sous Carte, avec la Barre de navigation : style Classic."
L["WN48_2_TITLE"] = "Texte de la liste des quêtes"
L["WN48_2_TEXT"] = "Taille de police de la liste des quêtes et Taille de police du texte de quête agrandissent les listes et le texte de quête de la carte, et Liste sur le parchemin du jeu place la liste sur la page du journal de quêtes du jeu au lieu de la pierre sombre. Elles partent de l'aspect du jeu ; activez-les dans les options (/fcui), sous Carte."
L["WN48_3_TITLE"] = "Guilde comme dans Era"
L["WN48_3_TEXT"] = "L'onglet de guilde suit la disposition de Classic Era : ses en-têtes de colonne, la barre au-dessus du message du jour, les totaux, les boutons et la case d'affichage des membres hors ligne sont où Era les place, et les noms de classe s'affichent en blanc."
L["WN48_4_TITLE"] = "Banque comme dans Era"
L["WN48_4_TEXT"] = "La banque garde la grille plus grande de Forever et prend dessous la disposition d'Era : une rangée d'emplacements de sac en taille réelle, la ligne d'achat et votre argent sur une bande en bas."
L["WN48_5_TITLE"] = "Territoire dans les noms de zone"
L["WN48_5_TEXT"] = "Le territoire d'une zone, comme Territoire de l'Alliance, s'affiche aussi hors des capitales, comme en 1.x. Pour garder les noms du jeu, décochez Territoire dans les noms de zone dans les options (/fcui), sous Autre."
L["WN48_6_TITLE"] = "Places de la disposition classique"
L["WN48_6_TEXT"] = "Le bouton Disposition classique et la configuration de la première connexion placent vos cadres de joueur, de cible et de focalisation et les barres 4 et 5 où Classic Era les met. Rien ne bouge tout seul : appuyez sur Disposition classique dans la fenêtre des options pour les utiliser."
L["WN48_7_TITLE"] = "Barre du bas"
L["WN48_7_TEXT"] = "Le bouton de la carte du monde vient après le bouton social, comme dans Era, et le dessin du micro-menu est celui d'Era, plus sombre vers son bout droit, avec la fenêtre de latence, le trousseau de clés et les sacs à côté, où Era les place."
L["WN48_8_TITLE"] = "Petites options"
L["WN48_8_TEXT"] = "La fenêtre « Vous avez reçu » du jeu pour un butin rare, un jet gagné ou une amélioration est masquée, car 1.x n'en avait pas ; Avis de butin la ramène. Masquer la recherche des sacs et Masquer le bouton de rangement retirent ces éléments des sacs. Les trois sont désactivées par défaut ; activez-les dans les options (/fcui), sous Autre et Sacs. Les coordonnées de la carte sous Carte sont des réglages du jeu lui-même."
L["WN48_9_TITLE"] = "Sur Retail"
L["WN48_9_TEXT"] = "L'œil de la recherche de groupe tourne autour de la minicarte et se redimensionne dans les options de minicarte de notre mode édition, le critique et la hâte montrent les infobulles du jeu, et Masquer le bouton d'aide de la carte masque son bouton de tutoriel. Désactivé par défaut ; activez-le dans les options (/fcui), sous Carte."
L["WN48_10_TITLE"] = "Corrections"
L["WN48_10_TEXT"] = "La lueur des affaiblissements du groupe est un anneau autour du portrait, une page pillée vide passe à la suivante, l'œil de la recherche de groupe grandit avec la minicarte et ne donne plus d'erreur ni ne disparaît en mode édition, le menu de colonne de la liste Qui choisit et trie une colonne directement, et les pages de quête complètent les récompenses arrivées tard. Inspecter les talents en combat n'affiche que notre fenêtre, et un combat qui commence pendant un déplacement arrête la fenêtre là où elle est."
L["WN47_1_TITLE"] = "Guilde et communautés"
L["WN47_1_TEXT"] = "La fenêtre Guilde et communautés est maintenant une page sociale : elle porte les onglets Amis, Qui, Guilde et Raid dans ses deux modes, et son petit mode a la taille de la fenêtre sociale, avec l'anneau et le portrait."
L["WN47_2_TITLE"] = "Profils en texte"
L["WN47_2_TEXT"] = "Exporter et Importer sur la page des profils : un profil en une ligne de texte à copier vers un autre compte ou un ami, et de retour dans un nouveau profil."
L["WN47_3_TITLE"] = "Largeur du menu"
L["WN47_3_TEXT"] = "La fenêtre de réglage du micro-menu a un curseur Largeur du menu à côté de Taille : la rangée s'élargit ou se rétrécit, les boutons gardant leur taille. Au-delà de 100 %, Taille élargit maintenant le décor avec la rangée."
L["WN47_4_TITLE"] = "Fenêtre sociale"
L["WN47_4_TEXT"] = "La fenêtre sociale reste en place après une recherche Qui, le bouton de statut sous le titre accepte les clics, les boutons du micro-menu masqués n'ouvrent plus leur fenêtre depuis une place vide."
L["WN47_5_TITLE"] = "Carte en combat"
L["WN47_5_TEXT"] = "La carte du monde n'est protégée en combat que pendant que la carte classique de cet addon la dispose, donc les addons de carte fonctionnent en combat avec la carte classique désactivée."
L["WN46_1_TITLE"] = "Fenêtre sociale"
L["WN46_1_TEXT"] = "L'onglet Raid est de retour dans la rangée d'onglets de la fenêtre sociale sur les clients où le nouveau système social du jeu est désactivé, et le petit onglet sous Alliés récents indique à nouveau Rejoindre rapidement au lieu de Raid. La fenêtre ne se déplace plus que par sa barre de titre, si bien que le bouton de statut sous le titre accepte de nouveau les clics."
L["WN45_1_TITLE"] = "Collections sur Retail"
L["WN45_1_TEXT"] = "La fenêtre classique des collections est aussi sur Retail : montures, mascottes avec votre équipe de combat à côté, jouets et héritages en pages de livre, campements et apparences, chaque page avec les filtres du jeu. Faites glisser un aperçu pour le tourner, la molette sur une créature la rapproche, un glisser du bouton droit déplace une apparence ; le bouton à côté des flèches le remet en place. Fenêtre des collections est activée par défaut, dans les options (/fcui) sous Personnage, sorts, talents."
L["WN45_2_TITLE"] = "Une recherche sur chaque page"
L["WN45_2_TEXT"] = "Chaque page d'options a son propre champ de recherche en haut à droite, qui ne parcourt que cette page ; la recherche en haut à gauche couvre toujours toutes les pages. Tout désactiver et Options par défaut sont passés en bas à droite. Fenêtres de style classique a disparu de Toutes les fenêtres : chaque fenêtre est désormais sa propre case, et aucune ligne ne se grise à cause d'une autre."
L["WN45_3_TITLE"] = "Recherche de statistiques"
L["WN45_3_TEXT"] = "Un champ de recherche dans l'onglet Statistiques de la fenêtre du personnage trouve les statistiques par nom ou par catégorie. Désactivée par défaut ; activez-la dans les options (/fcui), sous Personnage, sorts, talents."
L["WN45_4_TITLE"] = "Taille de l'interface"
L["WN45_4_TEXT"] = "La disposition classique règle l'échelle de l'interface du jeu sur la taille de Classic Era, 90 % sur la plupart des écrans. Tout désactiver, dans la barre latérale des options, propose maintenant de rétablir votre ancienne taille, avec une case dans sa confirmation, et Options par défaut propose la taille d'Era tant que vous en avez une autre. Les deux confirmations conseillent d'enregistrer d'abord un profil pour revenir à vos réglages, et la page FAQ explique la taille."
L["WN45_5_TITLE"] = "Liste Qui désactivée"
L["WN45_5_TEXT"] = "Avec Liste Qui désactivée, l'onglet Qui de la fenêtre sociale et l'onglet latéral Qui de la recherche de groupe ouvrent la liste Qui propre à Forever, une page de la recherche de groupe ; Annonce et Parcourir ramènent aux pages classiques. Masquer l'onglet Qui retire l'onglet du bas de la fenêtre sociale. Désactivé par défaut ; activez-le dans les options (/fcui), sous Social."
L["WN45_6_TITLE"] = "Sacs et barres"
L["WN45_6_TEXT"] = "Masquer les graphismes du trousseau retire les graphismes du trousseau de la barre. Désactivé par défaut ; activez-le dans les options (/fcui), sous Sacs. Sur Retail, le sac de composants a ses propres choix sous Sacs : en graphisme de clé, en graphisme de sac tassé, un emplacement entier ou masqué. Une seule barre n'active plus rien d'autre et liste ses paires dessous, et les flèches de page modernes se placent au-dessus du griffon avec Griffons devant les barres."
L["WN45_7_TITLE"] = "Corrections"
L["WN45_7_TEXT"] = "Sur Retail, un druide sélénien voyait deux barres de mana ; seule la nôtre s'affiche désormais, sous la puissance astrale. La page Métiers du grimoire revient à sa place quand une autre fenêtre se ferme, et sur Retail la fenêtre d'artisanat s'ouvre à côté du grimoire, pas dessus, avec sa bordure sous la rangée Créer ; son bouton d'agrandissement a disparu, la page du jeu s'ouvrant depuis la recette. L'œil de la recherche de groupe reste sur le bord de la minicarte en mode Édition, et sur Retail un glisser avec Maj le fait longer le bord. La case du micro-menu en mode Édition ne clignote plus dans le coin, l'alerte d'un micro-bouton pulse avec la lueur 1.x, les plaques de noms amicales ne clignotent plus en violet sur Retail, un aperçu des collections s'ouvre cadré, Tout désactiver décoche aussi les fenêtres sous une case parente, Jets de butin est activé par défaut pour les nouvelles installations, et la recherche des options garde lumineuses les lignes au-dessus d'une correspondance."
L["WN44_1_TITLE"] = "Thèmes d'une seule couleur"
L["WN44_1_TEXT"] = "Les thèmes dessinent désormais tout d'une seule couleur unie par défaut, comme un mode sombre. Pour rendre les textures aux parties choisies, activez Couleur texturée dans les options (/fcui), sous Apparence. Avec thème choisit quelles parties prennent le thème. Le parchemin prend aussi le thème, avec un texte clair sur une page sombre. Si vous utilisiez déjà un thème, votre apparence est conservée."
L["WN44_2_TITLE"] = "Pièces classiques"
L["WN44_2_TEXT"] = "L'or, l'argent et le cuivre montrent les pièces rondes de Classic Era dans vos sacs, chez les marchands, dans le courrier, les quêtes et les infobulles. Décochez Pièces classiques dans les options (/fcui), sous Apparence, pour les modernes."
L["WN44_3_TITLE"] = "Une seule barre"
L["WN44_3_TEXT"] = "Une seule barre masque aussi la barre de latence et place le trousseau avec les sacs par leurs propres options, qui les rétablissent. Flèches de page modernes montre les petites flèches de page du jeu sur le griffon gauche. Elle est désactivée par défaut, activez-la dans les options, sous Une seule barre."
L["WN44_4_TITLE"] = "Sacs"
L["WN44_4_TEXT"] = "Masquer les bordures de qualité et Masquer la pièce de camelote retirent de vos objets les bordures colorées de qualité et la pièce d'or du marchand. Les deux sont désactivées par défaut, activez-les dans les options, sous Sacs."
L["WN44_5_TITLE"] = "Minicarte"
L["WN44_5_TEXT"] = "Masquer les bordures des boutons a une liste Boutons pour choisir quels boutons perdent leur anneau, le bouton de minicarte de chaque addon peut avoir son propre choix, et l'œil de la recherche de groupe reste sur le bord de la minicarte."
L["WN44_6_TITLE"] = "Corrections"
L["WN44_6_TEXT"] = "Une barre d'info cliquée garde son nom jaune tant que la souris reste dessus. Une option masque l'en-tête Tous les objectifs du suivi, les options ont une page Toutes les fenêtres, et les choix des listes de statistiques suivent les profils."
L["WN43_1_TITLE"] = "Minicarte carrée"
L["WN43_1_TEXT"] = "Minicarte carrée rend la carte carrée, dans le métal de la bordure ronde, les boutons de la bordure suivant son bord. Elle est désactivée par défaut, activez-la dans les options (/fcui), sous Minicarte. Tant que Rotation de la minicarte du jeu est activée, la carte reste ronde."
L["WN43_2_TITLE"] = "Minicarte"
L["WN43_2_TEXT"] = "Bouton de fermeture de la minicarte met le X d'Era sur la barre de zone : un clic masque la carte, un autre la fait revenir. Il est désactivé par défaut, activez-le dans les options, sous Minicarte. En mode Édition, la barre de zone peut maintenant passer sous la carte, l'horloge est à la place d'Era, dans le cadre d'Era, et Maj pour déplacer les boutons de la minicarte peut être désactivé pour un simple glisser."
L["WN43_3_TITLE"] = "Barres de nom"
L["WN43_3_TEXT"] = "Les chiffres de vie du jeu sur nos barres peuvent se placer à droite, répartis ou à gauche : choisissez-le sous Barres de nom dans les options (/fcui). Nos barres affichent maintenant les chiffres que choisissent les options d'information des barres de nom du jeu, et le nom de la barre sous la souris devient jaune, comme dans Classic Era."
L["WN43_4_TITLE"] = "Bannière de niveau"
L["WN43_4_TEXT"] = "La grande bannière de niveau du jeu est maintenant masquée, la 1.x n'en avait pas. Pour la revoir, activez Bannière de niveau dans les options (/fcui), sous Autre."
L["WN43_5_TITLE"] = "Fenêtres"
L["WN43_5_TEXT"] = "La fenêtre des macros et son sélecteur d'icônes prennent l'aspect d'Era. Sur la fiche du personnage, les cadres de caractéristiques prennent le bord gris d'Era, chaque personnage garde son propre choix de volets de caractéristiques, et les sous-titres de l'onglet Statistiques utilisent le plus et le moins classiques. Options par défaut active maintenant aussi Barres à la taille classique ; une ligne de discussion dit comment l'annuler."
L["WN43_6_TITLE"] = "Corrections"
L["WN43_6_TEXT"] = "Sur la cible et la focalisation avec des barres de vie épaisses, les soins entrants remplissent toute la barre et commencent juste où finit la vie. Le filtre Afficher les niveaux des quêtes de la carte ne fonctionne plus à l'envers. Les séparateurs de la barre 1 restent estompés sous la souris, la page d'un objet de quête ne dépasse plus son parchemin, avec les bordures de boutons masquées l'anneau du calendrier disparaît aussi et la loupe de suivi est centrée, et les options grisées affichent de nouveau leur info-bulle."
L["WN42_1_TITLE"] = "Minicarte"
L["WN42_1_TEXT"] = "Les boutons de minicarte des autres addons, et notre bouton d'options, peuvent être affichés, affichés au survol ou masqués sans les regrouper : Boutons d'addons, sous Minicarte dans les options (/fcui). L'icône de pistage est aussi un menu déroulant : affichée, au survol ou masquée. Masquer le N (nord) retire le N du haut du bord de la minicarte ; désactivé par défaut, active-le sous Minicarte dans les options. Avec le calendrier derrière jour et nuit, survoler cette icône montre le calendrier à sa place."
L["WN42_2_TITLE"] = "Discussion"
L["WN42_2_TEXT"] = "Les onglets du chat et le cadre de la zone de saisie peuvent chacun être affichés, affichés au survol ou masqués : Onglets du chat et Cadre de la zone de saisie, sous Discussion dans les options (/fcui). Les afficher au survol, sous Masquer les boutons de discussion, ramène les boutons masqués tant que la souris est sur le chat ; désactivé par défaut, active-le là dans les options."
L["WN42_3_TITLE"] = "Sacs"
L["WN42_3_TEXT"] = "Les options de la barre des sacs sont maintenant sur la page Sacs. Masquer aussi les graphismes du trousseau, sous Masquer les graphismes de la barre des sacs, retire les graphismes du trousseau avec ceux des sacs tant que le trousseau n'est pas sur la barre ; désactivé par défaut, active-le dans les options (/fcui), sous Sacs. Avec la barre des sacs sur sac à dos seul et repliée, le sac de composants reste et le trousseau revient au survol. Dans le sac unique, survoler un bouton de sac éclaire de nouveau ses emplacements, ceux du trousseau aussi."
L["WN42_4_TITLE"] = "Fondu au survol"
L["WN42_4_TEXT"] = "Tout ce qui s'affiche au survol apparaît et disparaît maintenant en un bref fondu au lieu de surgir."
L["WN42_5_TITLE"] = "Corrections"
L["WN42_5_TEXT"] = "Avec les Fenêtres de métier désactivées, le livre des métiers ne montre plus de cadre sombre au-delà de son bord. Changer une option sur nos pages dans les réglages du jeu ne pose plus le bord de notre fenêtre sur celle du jeu, et ces pages descendent jusqu'à son pied ; la page des options garde aussi sa position de défilement. Les menus et sous-menus prennent l'aspect classique avant de s'afficher. La fenêtre des collections garde ses filtres, et avec un addon qui déplace les fenêtres, la grande taille du livre des métiers fonctionne et le grimoire ne saute plus."
L["WN41_1_TITLE"] = "Un seul sac"
L["WN41_1_TEXT"] = "Activer la rangée des emplacements de sac dans le sac unique ne casse plus sa disposition avec une erreur, et avec les sections par type de sac, les emplacements du trousseau ont leur propre section."
L["WN41_2_TITLE"] = "Touche du grimoire"
L["WN41_2_TEXT"] = "La touche et le bouton du grimoire ouvrent de nouveau le grimoire au lieu de la dernière page de métier ou de Collections montrée."
L["WN40_1_TITLE"] = "Fenêtre des collections"
L["WN40_1_TEXT"] = "Montures, mascottes, jouets, héritages et apparences dans une fenêtre classique à onglets latéraux, avec les vues de modèle du jeu, un champ de recherche et un seul menu Filtre. Elle s'ouvre par le bouton ou la touche Collections et, ce micro-bouton masqué, par un onglet Collections au pied du grimoire, comme une page du livre. Activée par défaut ; Fenêtre des collections, sous Autre dans les options (/fcui), la désactive, et Onglet Collections sous Grimoire masque l'onglet."
L["WN40_2_TITLE"] = "Une seule barre"
L["WN40_2_TEXT"] = "Avec Une seule barre activée, Barre principale seule lui retire les flèches de page et la barre de latence et met le trousseau avec les sacs. Activer Une seule barre masque maintenant aussi l'habillage des sacs, du micro-menu et du trousseau, rapproche les boutons de sacs et place le micro-menu dans le coin de l'écran, les sacs dessus. Une seule barre est désactivée par défaut ; activez-la dans les options (/fcui), sous Barres d'action, où Trousseau avec les sacs et Sacs rapprochés sont aussi des cases à part."
L["WN40_3_TITLE"] = "Fenêtres de style classique"
L["WN40_3_TEXT"] = "Cadres de fenêtre devient Fenêtres de style classique, sur la page Apparence des options : un interrupteur, avec une case par fenêtre en dessous dans une liste déroulante avec recherche. Tant qu'il est désactivé, les options de fenêtre des autres pages sont grisées et leur infobulle dit quoi activer. L'activer ou le désactiver, ou la case d'une fenêtre, demande un rechargement, car une fenêtre ouverte garde le cadre avec lequel elle a été construite."
L["WN40_4_TITLE"] = "Mode édition"
L["WN40_4_TEXT"] = "La barre de totems a en mode édition les réglages de la barre de postures : orientation, rangées, taille des icônes et espacement. Les cadres de focus et de familier peuvent aussi montrer leurs améliorations au-dessus, depuis leurs dialogues du mode édition, et le petit cadre de focus montre ses affaiblissements au-dessus également. La flèche des améliorations est maintenant un seul menu déroulant dans les options : affichée, au survol ou masquée."
L["WN40_5_TITLE"] = "Un seul sac"
L["WN40_5_TEXT"] = "Un seul sac peut montrer des sections par type de sac ou par sac, les emplacements du trousseau après ceux du dernier sac, dans son laiton (le bouton du trousseau ouvre alors le sac unique), et les emplacements de sac équipés. Chacun est une case sous Un seul sac dans les options (/fcui), sous Sacs, désactivée par défaut ; activez-la là."
L["WN40_6_TITLE"] = "Pages du grimoire et carte"
L["WN40_6_TEXT"] = "Métiers et Collections comptent comme des pages du grimoire : son bouton reste enfoncé dessus, sa touche ferme la page, et le livre se rouvre sur la dernière page montrée. La carte du monde classique s'ouvre en fenêtre à la hauteur de la carte du jeu et garde taille et place pendant un combat."
L["WN40_7_TITLE"] = "Cadres d'unité et barre d'XP"
L["WN40_7_TEXT"] = "Les barres de vie épaisses des joueurs ennemis montrent leur couleur de classe, activé par défaut (Joueurs ennemis aussi, sous Vie aux couleurs de classe). Cadres d'élite sépare Joueurs et PNJ, chacun gardant ou habillant son dragon. L'infobulle de la barre d'XP peut dire combien d'XP de repos il reste : XP de repos dans l'infobulle de la barre d'XP, sous Barres d'action, désactivé par défaut ; activez-le dans les options (/fcui)."
L["WN40_8_TITLE"] = "Corrections"
L["WN40_8_TEXT"] = "Un clic droit sur la barre de ressource d'un cadre d'unité rouvre son menu, les noms en cyrillique s'affichent sur les cadres d'unité et les plaques de nom, Pourcentage de menace désactivé masque aussi le nombre du jeu, une quête cliquée dans un addon de suivi ouvre notre journal des quêtes, et un bouton de minicarte masqué par son propre addon reste masqué. La taille pleine du livre des métiers est le livre classique dessiné plus grand. Une fenêtre du jeu dont le style classique est désactivé est laissée au jeu et aux autres addons, rien de nous dessus, et la case de déverrouillage de la carte est alors grisée. Inspecter un joueur montre toujours les onglets Personnage et JcJ. Options par défaut (avant Réinitialiser les options) compte les barres de taille classique comme défaut avec notre disposition. Petites corrections sur les icônes de contrôle des plaques de nom, la lueur de mana du druide, la boîte du menu du jeu, les longs menus du jeu et les boîtes du mode édition."
L["WN39_1_TITLE"] = "Marqueurs de carte d'Era"
L["WN39_1_TEXT"] = "Sur les cartes de Kalimdor et des Royaumes de l'Est, les capitales montrent de nouveau la tour grise d'Era et les villages sa maison jaune, avec le nom du village au survol. Activé par défaut ; Marqueurs de villes et villages d'Era, sous Carte dans les options (/fcui), le désactive."
L["WN39_2_TITLE"] = "Autres addons de barres d'action"
L["WN39_2_TEXT"] = "Quand un autre addon prend les barres d'action, la barre classique s'efface au lieu de se dessiner dessous. Une fenêtre le dit une fois, et une ligne dans la discussion à chaque connexion jusqu'à ce que vous désactiviez Avertissement de barres prises sous Messages de l'addon dans les options. Messages de l'addon fait aussi taire la note de bienvenue."
L["WN39_3_TITLE"] = "Flash de dégâts"
L["WN39_3_TEXT"] = "Le cadre du joueur ne fait plus clignoter en rouge la vie que vous venez de perdre, comme en 1.x. Désactivé par défaut ; pour le retrouver, activez-le dans les options (/fcui) : Flash de dégâts, sous Cadres d'unité."
L["WN39_4_TITLE"] = "Addons de déplacement de fenêtres"
L["WN39_4_TEXT"] = "Laisser les fenêtres du jeu aux autres addons cesse de placer, redimensionner et verrouiller les fenêtres propres au jeu, pour qu'un addon de déplacement de fenêtres puisse s'en charger ; les nôtres gardent leur cadenas. Désactivé par défaut ; activez-le dans les options, sous Autre. Une nouvelle question de la FAQ explique pourquoi un tel addon déplace certaines fenêtres et pas d'autres."
L["WN39_5_TITLE"] = "Corrections"
L["WN39_5_TEXT"] = "La barre des sacs au survol montre les sacs tant que la souris est n'importe où sur la rangée, entre deux sacs aussi, et le survol propre du sac de composants ne l'efface plus hors de la barre classique. La carte classique ouverte en combat prend tout de suite sa taille et sa place classiques, Échap fonctionne de nouveau après une fenêtre de métier, et activer ou désactiver une barre d'action replace aussitôt la barre classique."
L["WN38_1_TITLE"] = "Minicarte"
L["WN38_1_TEXT"] = "Après la dernière mise à jour du jeu, le bouton de pistage et la barre de zone de la minicarte retrouvent leur aspect 1.x, et le nom de la zone retrouve la taille d'Era. Le jeu n'affiche plus d'indicateur de difficulté à cet endroit, donc son choix disparaît des options."
L["WN38_2_TITLE"] = "Corrections"
L["WN38_2_TEXT"] = "Attaquer ne déclenche plus d'erreur du compteur de dégâts nommant ClassicUI Forever, même avec le compteur de dégâts désactivé, et un combat ne déclenche plus d'erreur d'action bloquée sur la barre des sacs."
L["WN37_1_TITLE"] = "Options en deux volets"
L["WN37_1_TEXT"] = "Les options (/fcui) listent leurs pages à gauche, avec la recherche, et affichent la page à droite. Aucune option et Réinitialiser les options agissent par page ou pour toutes, et Réinitialiser les fenêtres remet chaque fenêtre à sa taille et à sa place."
L["WN37_2_TITLE"] = "Barre des sacs"
L["WN37_2_TEXT"] = "Choisissez Barre des sacs dans les options (/fcui), sous Fenêtres de sacs : masquée, affichée seulement jusqu'à l'ouverture des sacs ou au survol, ou sac à dos seul, où une petite flèche à côté du sac à dos, visible tant que la souris le survole, déplie les sacs."
L["WN37_3_TITLE"] = "Barre 2 à côté de la barre 1"
L["WN37_3_TEXT"] = "Choisissez Barre 2 : à droite de la barre 1 sur la bande, ou à gauche, dans les options (/fcui), sous Barre classique : la barre 2 à son emplacement par défaut prolonge les logements de pierre de la bande à côté de la barre 1, le reste de la bande après les deux."
L["WN37_4_TITLE"] = "Menu d'options du grimoire"
L["WN37_4_TEXT"] = "La ligne de recherche du grimoire a un menu d'options : Masquer les passifs, Grouper les sorts semblables en menus déroulants (ils se glissent aussi sur les barres en combat) et Afficher tous les rangs de sort. Activez-les là, ou dans les options (/fcui) sous Grimoire."
L["WN37_5_TITLE"] = "Corrections"
L["WN37_5_TEXT"] = "Les attaques et ordres du familier se glissent depuis l'onglet du familier en combat. Le grimoire ne s'envole plus après un combat avec la fenêtre de butin ouverte, une fenêtre de métier ouverte en combat affiche ses cadres, déplacer la carte avec un addon de carte garde la carte, et la lueur de survol d'une plaque de nom s'éteint quand la souris part. Sept nouvelles questions dans la FAQ."
L["WN37_6_TITLE"] = "Fenêtres"
L["WN37_6_TEXT"] = "Les fenêtres du jeu qu'un déplaceur de fenêtres tient lui sont laissées. Une fenêtre du jeu n'en ferme une autre que si les deux sont du genre qu'Era fermait, les autres restent en place quand l'une est glissée ou redimensionnée hors de la rangée, et une réinitialisation remet une fenêtre du jeu sur son emplacement."
L["WN36_1_TITLE"] = "Arbres de l'Héritage côte à côte"
L["WN36_1_TEXT"] = "Activez Trois arbres côte à côte dans les options (/fcui), sous Fenêtre de l'Héritage, pour voir à la fois les trois arbres de la fenêtre de l'Héritage, avec un seul Appliquer pour tous."
L["WN36_2_TITLE"] = "Les boutons de la minicarte s'enfoncent"
L["WN36_2_TEXT"] = "Les boutons de l'addon sur la minicarte, le sac des boutons d'addons et l'œil de la recherche de groupe s'enfoncent tant que vous maintenez la souris dessus, comme dans Era."
L["WN36_3_TITLE"] = "Corrections"
L["WN36_3_TEXT"] = "Les sorts canalisés affichent une barre d'incantation verte et la barre de respiration est de nouveau transparente, comme dans Era. Les onglets de la fenêtre du personnage s'enfoncent quand on clique, le compteur du journal de quêtes a des chiffres blancs et les en-têtes de quêtes de la carte du monde restent dorés. Le sac des boutons d'addons n'assombrit plus les icônes, et les boutons y entrent aussitôt après la connexion."
L["WN36_4_TITLE"] = "Bouton de l'Héritage"
L["WN36_4_TEXT"] = "Le bouton de l'Héritage ne reste plus enfoncé après la fermeture de sa fenêtre, et l'icône de l'Héritage sur la minicarte ouvre de nouveau sa fenêtre."
L["WN35_1_TITLE"] = "Trois arbres de talents"
L["WN35_1_TEXT"] = "Activez Trois arbres côte à côte dans les options (/fcui), sous Fenêtre des talents, pour voir les trois arbres à la fois. Sa liste Hauteur choisit si chaque arbre défile, si la fenêtre grandit ou si les rangées se resserrent."
L["WN35_2_TITLE"] = "Métiers en double volet"
L["WN35_2_TEXT"] = "Activez Double volet dans les options (/fcui), sous Fenêtres de métier, pour une fenêtre plus large : les recettes à gauche, la recette choisie et ses composants à côté."
L["WN35_3_TITLE"] = "Sac de composants dans le sac unique"
L["WN35_3_TEXT"] = "Activez Sac de composants dans le sac unique dans les options (/fcui), sous Fenêtres de sac, et ses emplacements s'ouvrent avec le sac unique comme ceux de n'importe quel sac, en premier ou en dernier, teintés de vert si vous le souhaitez. Survolez le bouton du sac de composants pour les mettre en évidence."
L["WN35_4_TITLE"] = "Onglets du grimoire"
L["WN35_4_TEXT"] = "Les onglets du grimoire suivent l'ordre d'Era pour chaque classe : pour un mage, Arcanes, Feu, Givre."
L["WN35_5_TITLE"] = "Corrections"
L["WN35_5_TEXT"] = "Les points de combo s'affichent par-dessus l'emblème JcJ de la cible, comme dans Era. Les barres de nom ne provoquent plus d'erreurs Lua en donjon. La touche sociale ouvre de nouveau la fenêtre sociale de l'addon avec la liste de guilde désactivée, et les fenêtres de l'addon s'alignent avec les addons qui centrent les fenêtres du jeu."
L["WN35_6_TITLE"] = "Aussi sur retail"
L["WN35_6_TEXT"] = "La page Qui n'affiche plus les onglets latéraux de la recherche de groupe, qui ouvrent celle de WoW Forever."
L["WN34_1_TITLE"] = "Placement des fenêtres"
L["WN34_1_TEXT"] = "Les fenêtres de l'addon s'ouvrent en une rangée après les fenêtres du jeu, dans l'ordre où vous les ouvrez, et s'alignent avec les addons qui déplacent les fenêtres du jeu. Une fenêtre que vous avez déplacée reste où vous l'avez mise. Faute de place, la plus ancienne se ferme, jamais en combat."
L["WN34_2_TITLE"] = "Grimoire et talents"
L["WN34_2_TEXT"] = "La grande fenêtre de grimoire et de talents du jeu se ferme quand vous ouvrez une fenêtre de l'addon qui n'a pas de place à côté, comme le jeu le fait avec ses propres fenêtres."
L["WN34_3_TITLE"] = "Poignée de taille"
L["WN34_3_TEXT"] = "Quand une fenêtre est déverrouillée, faites glisser la poignée de son coin inférieur droit pour la redimensionner, ou cliquez droit sur la poignée pour sa taille par défaut."
L["WN34_4_TITLE"] = "Œil de la recherche de groupe"
L["WN34_4_TEXT"] = "L'œil se place et se dimensionne de nouveau dans le mode Édition du jeu, avec Aimanter à la minicarte et Afficher hors file d'attente dans sa fenêtre."
L["WN34_5_TITLE"] = "Masquer les emplacements verrouillés"
L["WN34_5_TEXT"] = "Sans authentificateur sur votre compte, activez Masquer les emplacements verrouillés dans les options (/fcui), sous Fenêtres de sac, et le sac à dos se réduit aux emplacements utilisables."
L["WN34_6_TITLE"] = "Carte et caractéristiques"
L["WN34_6_TEXT"] = "Agrandie, la carte du monde garde son aspect d'Era, mise à l'échelle de l'écran. L'infobulle des dégâts donne la vitesse d'attaque et les dégâts par seconde de chaque main, comme dans Era."
L["WN34_7_TITLE"] = "Aussi sur Forever"
L["WN34_7_TEXT"] = "La carte du monde classique affiche vos coordonnées et celles du curseur sur une ligne dans son pied. L'onglet du familier affiche les lignes d'Era : Attaque, Puissance d'attaque, Dégâts, Défense et Armure."
L["WN33_1_TITLE"] = "Demandes d'amis"
L["WN33_1_TEXT"] = "Les onglets de la page des contacts sont Contacts, Alliances récentes et Demandes d'amis. Les demandes d'amis Battle.net attendent sur leur propre onglet, leur nombre dans son nom : choisissez-en une, puis Accepter ou Refuser. La liste des joueurs ignorés est dans le menu déroulant à côté de votre nom Battle.net."
L["WN33_2_TITLE"] = "Communautés en bouton"
L["WN33_2_TEXT"] = "Désactivé par défaut : activez Communautés en bouton dans les options (/fcui), sous Liste de guilde. Les communautés quittent alors la rangée d'onglets pour un bouton rond sur la page de guilde, et les quatre onglets gardent leur largeur de la 1.x. Sans guilde, un onglet des communautés prend la place de l'onglet de guilde."
L["WN33_3_TITLE"] = "Avis de mise à jour"
L["WN33_3_TEXT"] = "Quand quelqu'un de votre guilde ou de votre groupe a un ClassicUI Forever plus récent, une ligne dans la discussion vous le dit, avec un lien vers CurseForge. Messages de l'addon, sous Autre dans les options, la coupe avec les autres lignes de l'addon dans la discussion."
L["WN33_4_TITLE"] = "Changements de posture plus fluides"
L["WN33_4_TEXT"] = "Le camouflage du voleur, les formes de druide et les autres changements de posture ne provoquent plus de petit à-coup, et le suivi des quêtes ne saute plus quand ils ont lieu."
L["WN33_5_TITLE"] = "Détails JcJ"
L["WN33_5_TEXT"] = "Le panneau de détails de l'onglet JcJ est disposé comme celui du jeu, en pièces de la 1.x : une ligne sous votre rang, le titre des prochaines récompenses dans un cadre de fer et l'icône de la récompense dans un emplacement d'objet."
L["WN33_6_TITLE"] = "Onglet du familier"
L["WN33_6_TEXT"] = "L'onglet du familier montre ses points de dressage, et sa barre d'expérience montre ses chiffres en permanence, comme dans Era. Invoquer votre familier avec la page du personnage ouverte ne l'affiche plus à votre place."
L["WN33_7_TITLE"] = "Corrections"
L["WN33_7_TEXT"] = "Les boutons de posture, de familier et de possession suivent le thème. Les rangées d'onglets des fenêtres sociale et du personnage tiennent dans les langues longues comme l'allemand, sans libellé coupé. Les lignes de réputation s'allument sous la souris comme dans Era, et la fenêtre de butin s'ouvre au-delà de vos fenêtres ouvertes. Les lignes de l'addon dans la discussion commencent par son griffon."
L["WN32_1_TITLE"] = "La carte du monde d'Era"
L["WN32_1_TEXT"] = "La carte du monde affiche par défaut le grand cadre de carte d'Era, avec les listes déroulantes de continent et de zone et Zoom arrière dans son en-tête. Chaque style affiche la carte à sa propre taille ; redimensionnez-la quand vous voulez dans les fenêtres ClassicUI Forever (mode Édition). Pour la petite carte d'avant, choisissez Barre de navigation : aucune dans les options (/fcui), sous Carte du monde."
L["WN32_2_TITLE"] = "Options de la carte"
L["WN32_2_TEXT"] = "Un cadre Options de la carte en bas à droite de la carte du monde classique choisit ce que la carte affiche. Affichez-le toujours, au survol ou jamais dans les options, sous Carte du monde."
L["WN32_3_TITLE"] = "La barre d'incantation d'Era"
L["WN32_3_TEXT"] = "Les barres d'incantation des barres de nom prennent l'aspect d'Era, l'icône du sort dans l'emplacement gauche de la barre. La barre de nom de votre cible et celle sous la souris s'éclairent, et une incantation qui ne peut pas être interrompue garde son icône sous le bouclier d'Era. Pour l'ancienne barre, activez Barre d'incantation : icône à côté dans les options, sous Barres de nom."
L["WN32_4_TITLE"] = "Places libres des sacs"
L["WN32_4_TEXT"] = "Le nombre de places libres du sac à dos suit le réglage du jeu qui affiche l'espace libre des sacs, sous Interface dans les options du jeu, comme dans Era : désactivé tant que vous ne le cochez pas, et jamais affiché deux fois."
L["WN32_5_TITLE"] = "Corrections"
L["WN32_5_TEXT"] = "Masquer les bordures des boutons couvre aussi les boutons jour et nuit et de zoom de la minicarte, sans anneau en trop une fois désactivé. Dans les fenêtres ClassicUI Forever (mode Édition), les cadres des fenêtres fermées s'affichent là où se trouvent les fenêtres, et Réinitialiser la position remet la carte du monde à la place du jeu. Appliquer dans la fenêtre des talents tient dans son bouton. Les nouvelles installations ouvrent le journal de quêtes en double volet."
L["WN31_1_TITLE"] = "La fenêtre d'artisanat d'Era"
L["WN31_1_TEXT"] = "La fenêtre d'artisanat prend la taille, l'art et la disposition d'Era, avec un filtre par type d'objet fabriqué et des détails de recette qui défilent quand les composants dépassent."
L["WN31_2_TITLE"] = "Livre des métiers"
L["WN31_2_TEXT"] = "Le livre des métiers repose sur le parchemin du grimoire, l'emblème de chaque métier conservé. Les onglets à côté de la fenêtre des métiers s'affichent au survol ; choisissez toujours affichés ou masqués dans les options (/fcui), sous Livre des métiers. Pour la page à bandes, activez-y Livre style Cataclysm."
L["WN31_3_TITLE"] = "Sacs et trousseau"
L["WN31_3_TEXT"] = "Les sacs de la barre suivent l'orientation et la direction du mode Édition : Vertical les dresse en colonne. Le trousseau peut aussi se coucher : cochez Horizontal dans sa fenêtre du mode Édition."
L["WN31_4_TITLE"] = "Plus de l'allure d'Era"
L["WN31_4_TEXT"] = "Les livres et les lettres s'ouvrent dans la fenêtre de lecture d'Era, chaque bouton de la minicarte porte l'anneau de pierre d'Era, et les champs de texte des fenêtres contextuelles et le bouton des contacts de la fenêtre sociale prennent les formes d'Era."
L["WN31_5_TITLE"] = "Couleurs du thème"
L["WN31_5_TEXT"] = "Avec un thème personnalisé, plus d'art prend sa couleur, comme les bordures des listes et du défilement dans la plupart des fenêtres, la petite carte du monde et l'anneau jour et nuit de la minicarte."
L["WN31_6_TITLE"] = "Options"
L["WN31_6_TEXT"] = "Un curseur Distance max. de la caméra dans les options (/fcui), sous Autre, permet de reculer la caméra jusqu'à 4,0. Résultats seuls, près de la recherche des options, ne liste que les options qui correspondent."
L["WN31_7_TITLE"] = "Corrections"
L["WN31_7_TEXT"] = "Le butin ne ferme plus vos fenêtres ouvertes, les sacs de la barre n'ont plus de bordure argentée, et une réinstallation sur la disposition classique ne ramène plus les barres à la taille du jeu. Un nom coupé dans la liste Qui s'affiche en entier quand vous le pointez, et Apprendre se grise pour un nouveau métier quand les deux emplacements de métier sont pris, comme dans Era. Les barres de métier n'affichent plus deux verts, et le bouton d'amis près du chat n'ouvre plus la fenêtre sociale du jeu."
L["WN31_8_TITLE"] = "Aussi sur Forever"
L["WN31_8_TEXT"] = "La fenêtre du personnage a l'emplacement de munitions d'Era avec sa flèche vers l'emplacement à distance, et la fenêtre Recherche de groupe montre l'œil d'Era, qui tourne tant que vous êtes inscrit. Le grimoire ouvert en combat depuis son onglet Métiers ne s'ouvre plus décalé sur le côté, l'art de la fenêtre Héritage ne bouge plus entre ses pages, et les icônes du livre des métiers ne sautent plus pendant une fabrication. Les barres de l'onglet Compétences ont la taille et l'espacement d'Era, avec la bordure dorée d'Era sous la souris."
L["WN31_9_TITLE"] = "Œil de la recherche de groupe et icône de pistage"
L["WN31_9_TEXT"] = "L'icône de la recherche de groupe et l'œil de file d'attente du jeu ne font qu'un bouton : en file, l'œil prend la place de l'icône avec l'allure d'Era et tourne comme celui d'Era. L'icône de pistage a l'anneau plus grand d'Era ; pour garder l'ancienne taille, activez Icône de pistage : à la taille des autres boutons dans les options (/fcui), sous Minicarte."
L["WN31_10_TITLE"] = "Autres addons sur la minicarte"
L["WN31_10_TEXT"] = "Les addons qui rangent les boutons de la minicarte dans un sac laissent l'œil de la recherche de groupe et les autres icônes de la minicarte sur l'anneau, et le bouton des options montre son griffon dans leur sac. La bordure carrée de minicarte d'un autre addon n'apparaît plus autour de la minicarte ronde."
L["WN30_1_TITLE"] = "Corrections des barres d'action"
L["WN30_1_TEXT"] = "Des séparateurs dorés n'apparaissent plus entre les boutons de la barre principale quand elle change de page, comme avec Camouflage ou les formes de druide, et la bordure dorée d'une technique activée s'affiche de nouveau en entier."
L["WN30_2_TITLE"] = "Maître"
L["WN30_2_TEXT"] = "Apprendre dans la fenêtre classique du maître apprend de nouveau la compétence ou la recette choisie, et votre argent en dessous s'affiche en pleine luminosité."
L["WN29_1_TITLE"] = "Une fenêtre Héritage classique"
L["WN29_1_TEXT"] = "Le bouton et la touche Héritage ouvrent une fenêtre Héritage classique : la piste de récompenses et les défis sur les anciennes barres de compétence, avec une recherche et un filtre, et les arbres d'héritage dans l'ancienne fenêtre des talents. Activée par défaut ; désactivez-la dans les options (/fcui), sous Personnage et sorts."
L["WN29_2_TITLE"] = "Vos propres dispositions restent les vôtres"
L["WN29_2_TEXT"] = "Avec l'addon désactivé, les barres d'action de vos propres dispositions du mode Édition ne sont plus aux places de la barre classique. Les places enregistrées là auparavant sont rendues la prochaine fois que vous appuyez sur Recharger l'IU dans les options (/fcui) ou tapez /fcui off."
L["WN29_3_TITLE"] = "Corrections"
L["WN29_3_TEXT"] = "/fcui off désactive de nouveau l'addon. Cliquer sur un membre de guilde en combat ouvre ses détails. La fenêtre des options du jeu ne déverse plus d'erreurs après un combat, les niveaux de quête restent masqués avec l'option désactivée, et la flèche de défilement vers le bas de la discussion ne clignote plus."
L["WN29_4_TITLE"] = "Emplacements d'arme"
L["WN29_4_TEXT"] = "Les emplacements d'arme de la fenêtre du personnage sont centrés sur deux creux, sans le creux vide de l'emplacement à distance."
L["WN28_1_TITLE"] = "Alliés récents et Ignorés"
L["WN28_1_TEXT"] = "L'onglet Amis de la fenêtre sociale a les onglets Alliés récents et Ignorés à côté d'Amis. Alliés récents liste les joueurs avec qui vous avez groupé récemment et a une ligne de recherche ; Ignorés liste les joueurs que vous ignorez."
L["WN28_2_TITLE"] = "De nouveau la fenêtre sociale classique"
L["WN28_2_TEXT"] = "Depuis la dernière mise à jour du jeu, O et le bouton de guilde ouvraient la nouvelle fenêtre sociale du jeu. Ils ouvrent de nouveau la classique, ses onglets sont alignés et l'onglet Raid est de retour."
L["WN28_3_TITLE"] = "Corrections après la mise à jour du jeu"
L["WN28_3_TEXT"] = "Les points de combo affichent de nouveau les cinq orbes classiques. La bande sombre sur le modèle du personnage et le cadre sombre sur les pages d'annonce de la recherche de groupe ont disparu, le bouton de tri fonctionne en mode sac unique, et la recherche de groupe ne saute plus quand elle s'ouvre en combat."
L["WN28_4_TITLE"] = "Fenêtre de butin et sacs"
L["WN28_4_TEXT"] = "Avec Fenêtre de butin désactivée, la fenêtre de butin du jeu n'affiche plus deux carrés blancs dans ses coins. Le bouton de tri des sacs tient à côté du champ de recherche."
L["WN27_1_TITLE"] = "Moins de travail en arrière-plan"
L["WN27_1_TEXT"] = "Les barres de nom ne sont replacées que lorsqu'un réglage des barres de nom change, et non à chaque réglage modifié par le jeu ou par un autre addon. Les coordonnées de la minicarte ne sont mesurées que lorsqu'elles changent. Rien ne change à l'écran."
L["WN26_1_TITLE"] ="Couleurs de classe par cadre"
L["WN26_1_TEXT"] = "Vie aux couleurs de classe et Case du nom aux couleurs de classe sont désactivées par défaut ; activez-les dans les options (/fcui), sous Cadres d'unité. Chacune a maintenant en dessous un menu des cadres : Joueur, Cible et Focus, la cible peut ainsi porter sa couleur de classe pendant que votre propre cadre reste comme avant."
L["WN26_2_TITLE"] = "Couleur de la case du nom"
L["WN26_2_TEXT"] = "Un nouveau menu Couleur de la case du nom, sous Cadres d'unité, choisit les cadres dont la case du nom prend la couleur du jeu pour l'unité (bleu pour un joueur amical). Cible et Focus sont cochés, comme dans Classic Era ; décochez-en un pour une case unie. Joueur est désactivé par défaut ; activez-le dans les options (/fcui) pour colorer la vôtre."
L["WN26_3_TITLE"] = "Corrections"
L["WN26_3_TEXT"] = "Avec la barre de vie épaisse sur le nom, la case du nom du cadre du joueur n'apparaît plus derrière la barre. Décocher la case du nom aux couleurs de classe retire aussitôt la couleur de la cible et du focus."
L["WN25_1_TITLE"] = "Griffons"
L["WN25_1_TEXT"] = "Les griffons sont maintenant enregistrés avec la disposition du mode Édition, comme les éléments du jeu : chaque disposition garde ses propres emplacements pour eux, et Enregistrer sur une disposition prédéfinie du jeu demande une nouvelle disposition, qui les reprend. Un déplacement non enregistré est abandonné à la fermeture du mode Édition. La disposition classique des options les remet aux extrémités de la barre."
L["WN24_1_TITLE"] = "Sacs"
L["WN24_1_TEXT"] = "Les sacs ouverts ne sautent plus sur le côté quand vous équipez un objet par clic droit, en combat comme hors combat."
L["WN23_1_TITLE"] = "Minuteurs d'attaque"
L["WN23_1_TEXT"] = "Changer d'arme en combat ne déclenche plus d'erreur Lua à chaque image où la barre d'attaque est affichée, et l'éclair à chaque coup continue de fonctionner après le changement."
L["WN22_1_TITLE"] = "Métiers"
L["WN22_1_TEXT"] = "Un métier s'ouvre dans la fenêtre d'artisanat classique, et le livre des métiers est l'ancien petit livre, dans le cadre du grimoire. Le bouton de taille à côté du bouton de fermeture fait passer l'un ou l'autre à la fenêtre complète du jeu."
L["WN22_2_TITLE"] = "Grimoire et talents"
L["WN22_2_TEXT"] = "Un bouton Grimoire dans le micro-menu, à côté de Personnage, ouvre le grimoire classique. La fenêtre des talents du jeu porte le cadre classique, et le bouton Talents l'ouvre toujours sur vos talents."
L["WN22_3_TITLE"] = "Micro-menu et minicarte"
L["WN22_3_TEXT"] = "Hauts faits, Guide de l'aventurier et Logis quittent le micro-menu, car la 1.x n'en avait pas, et chacun a une icône sur la minicarte. Pour retrouver un bouton, décochez-le sous Masquer des micro-boutons dans les options (/fcui)."
L["WN22_4_TITLE"] = "Rejoindre rapidement"
L["WN22_4_TEXT"] = "Rejoindre rapidement a quitté la rangée d'onglets de la fenêtre sociale. Ouvrez Amis, puis Alliés récents : l'onglet Rejoindre rapidement sous la liste y mène, et l'onglet Alliés récents en revient."
L["WN22_5_TITLE"] = "Performances"
L["WN22_5_TEXT"] = "Les thèmes de couleur utilisent bien moins de processeur : le décor coloré ne suit celui du jeu que lorsque quelque chose change, et non à chaque image. Les menus du clic droit sur les portraits, les sacs et les fenêtres s'ouvrent sans à-coup."
L["WN22_6_TITLE"] = "Macros"
L["WN22_6_TEXT"] = "Un sort placé par Maj-clic depuis le grimoire classique dans une macro y entre avec son nom et son rang, comme depuis le grimoire du jeu ; il y entrait comme un lien de discussion, qu'une macro ne peut pas lancer. La fenêtre des macros a les onglets de Classic Era."
L["WN22_7_TITLE"] = "Macros"
L["WN22_7_TEXT"] = "Un sort placé par Maj-clic depuis le grimoire classique dans une macro y entre avec son nom et son rang, comme depuis le grimoire du jeu ; il y entrait comme un lien de discussion, qu'une macro ne peut pas lancer. Les talents y entrent aussi avec leur nom. La fenêtre des macros a les onglets de Classic Era."
L["WN22_8_TITLE"] = "Menus déroulants"
L["WN22_8_TEXT"] = "Les menus déroulants du jeu, comme le menu de statut (Disponible, Absent, Occupé) et le menu de suivi de la minicarte, ont maintenant le cadre de fer de Classic Era, qui contient leurs icônes et leurs flèches."
L["WN22_9_TITLE"] = "Réputation et monnaies"
L["WN22_9_TEXT"] = "Les deux onglets gardent les lignes classiques : espacement régulier, anciens en-têtes, une seule colonne de barres. Un groupe de factions a son bouton plus ou moins avec ses factions en retrait dessous, et le filtre est un petit bouton fléché en haut à droite."
L["WN22_10_TITLE"] = "Autres corrections"
L["WN22_10_TEXT"] = "Les onglets sous une fenêtre restent sur sa bordure inférieure ; à certaines tailles d'interface, ils montaient. Un Maj-clic sur un métier laisse le grimoire ouvert, les chiffres de mana d'un druide sous ses formes suivent le réglage Texte d'état du jeu, et l'onglet Aide ne montre que les questions de la version du jeu à laquelle vous jouez."
L["WN22_11_TITLE"] = "Fenêtres sur Retail"
L["WN22_11_TEXT"] = "Le sac de composants ne touche plus la barre de latence, la fenêtre du personnage n'a plus de fines lignes autour du modèle, la fenêtre sociale n'a qu'un onglet Qui, et les bordures des fenêtres sont placées comme sur Forever."
L["WN21_1_TITLE"] = "Liste de guilde"
L["WN21_1_TEXT"] = "Cliquer sur un membre ouvre ses notes et ses options pour chaque membre ; dans les grandes guildes, rien ne s'ouvrait pour beaucoup d'entre eux. La liste utilise aussi bien moins de processeur tant qu'elle est ouverte."
L["WN21_2_TITLE"] = "Partage de quêtes"
L["WN21_2_TEXT"] = "Partager la quête dans le journal de quêtes classique fonctionne pour n'importe quelle quête en un clic, y compris juste après la connexion. Cela ne marchait que pour les quêtes de la zone affichée en dernier par la carte du monde."
L["WN21_3_TITLE"] = "Fenêtres"
L["WN21_3_TEXT"] = "Une lettre ouverte a le cadre de fenêtre classique, comme la boîte de réception, et le panneau latéral de la fenêtre du personnage n'affiche plus de fine ligne transparente à certaines tailles d'interface."
L["WN20_1_TITLE"] ="Détails du rang JcJ"
L["WN20_1_TEXT"] = "L'onglet JcJ de la fenêtre du personnage peut afficher les détails de votre rang et les récompenses du rang suivant. Cliquez sur la flèche en bas à droite de l'onglet pour ouvrir le panneau latéral."
L["WN20_2_TITLE"] = "Sac des boutons d'addons"
L["WN20_2_TEXT"] = "Sa place par défaut est désormais à gauche de l'horloge, à l'écart de l'œil de la recherche de groupe, et il laisse sur la minicarte nos propres icônes, comme Héritage. Le bouton Disposition classique remet aussi en place les boutons de la minicarte que vous avez déplacés."
L["WN20_3_TITLE"] = "Autres addons"
L["WN20_3_TEXT"] = "Les parties de ClassicUI Forever que vous désactivez ne touchent plus aux cadres du jeu : les addons qui les modifient gardent leur apparence."
L["WN19_1_TITLE"] = "Icônes de la minicarte"
L["WN19_1_TEXT"] = "N'importe quel bouton du micro-menu peut maintenant aller sur la minicarte en icône : cochez-le sous Boutons du micro-menu sur la minicarte dans les options (/fcui). Héritage et la recherche de groupe sont activés par défaut, Héritage est donc de nouveau accessible. Maintenez Maj et faites glisser pour déplacer nos boutons de minicarte autour de l'anneau."
L["WN19_2_TITLE"] = "Suivi de quêtes"
L["WN19_2_TEXT"] = "Le suivi des objectifs peut être le suivi de quêtes simple de Classic Era. Désactivé par défaut ; pour l'activer, réglez Suivi des objectifs sur celui de Classic Era dans les options (/fcui), sous Quêtes. Clic sur un titre pour ouvrir la quête, Maj-clic pour ne plus la suivre, clic droit pour plus."
L["WN19_3_TITLE"] = "Fenêtre des options"
L["WN19_3_TEXT"] = "La fenêtre des options est plus grande et ses longues listes sont maintenant des menus déroulants, il y a donc moins à faire défiler."
L["WN19_4_TITLE"] = "Pourcentage de menace"
L["WN19_4_TEXT"] = "Le pourcentage de menace peut ne s'afficher qu'en groupe ou en donjon : activez Seulement en groupe ou en donjon dans les options (/fcui), sous Cadres d'unité. Désactivé par défaut."
L["WN19_5_TITLE"] = "Touches de Classic Era"
L["WN19_5_TEXT"] = "L'infobulle du bouton du menu du jeu a les descriptions de Classic Era, les menus déroulants utilisent le cadre de fer de Classic Era, et les boutons du micro-menu ne deviennent plus gris quand le menu du jeu est ouvert."
L["WN19_6_TITLE"] = "Corrections"
L["WN19_6_TEXT"] = "Réinitialiser les options garde les barres de taille classique, les thèmes personnalisés colorent entièrement les onglets des options, le décor de la barre classique reste affiché dans la disposition ClassicUI Forever, le bouton des options ne recouvre plus la loupe de suivi, et avec Minicarte décochée, les icônes de la minicarte masquées par un autre addon restent masquées."
L["WN18_1_TITLE"] = "Métiers"
L["WN18_1_TEXT"] = "La fenêtre de métier peut maintenant suivre une recette (ses composants s'affichent dans le suivi des objectifs), filtrer par emplacement d'équipement et lier votre métier dans la discussion avec le maillon à côté de son titre. La touche des métiers ouvre de nouveau le livre des métiers."
L["WN18_2_TITLE"] = "Dragons d'élite"
L["WN18_2_TEXT"] = "Les ennemis d'élite peuvent afficher un dragon doré autour de leur niveau sur la barre de nom, les rares un dragon argenté : activez Dragons d'élite dans les options (/fcui), sous Barres de nom. Avec un thème personnalisé, Ignorer le thème pour les cadres d'élite et Ignorer le thème pour les dragons des barres, sous Thème personnalisé, gardent les dragons dorés et argentés. Tout est désactivé par défaut."
L["WN18_3_TITLE"] = "Lueur de combat"
L["WN18_3_TEXT"] = "Pour arrêter la pulsation rouge du cadre du joueur pendant que vous attaquez, activez Masquer la lueur de combat dans les options (/fcui), sous Cadres d'unité. Désactivé par défaut."
L["WN18_4_TITLE"] = "Barres d'incantation"
L["WN18_4_TEXT"] = "Les sorts interrompus de la cible, du focus et des barres de nom deviennent maintenant rouges et indiquent seulement Interrompu, comme dans Classic Era. Pour voir qui a interrompu, activez Nommer qui interrompt dans les options (/fcui), sous Barres d'incantation. Les canalisations s'affichent en vert."
L["WN18_5_TITLE"] = "Difficulté d'instance"
L["WN18_5_TEXT"] = "Le drapeau de difficulté que le jeu affiche sur la minicarte en donjon et en raid est maintenant masqué. Pour le retrouver, choisissez affichée ou au survol sous Minicarte, dans les options (/fcui)."
L["WN18_6_TITLE"] = "Disposition classique"
L["WN18_6_TEXT"] = "La silhouette de durabilité ne se cache plus derrière les barres latérales, et les améliorations se placent aux emplacements de Classic Era à côté de la minicarte. La disposition propose aussi la taille d'interface de Classic Era quand la vôtre est différente."
L["WN18_7_TITLE"] = "Apparence"
L["WN18_7_TEXT"] = "Les menus ont le fond noir de Classic Era, et les barres de nom ont la taille de Classic Era. La partie vide des barres d'expérience et de réputation est ombrée comme dans Classic Era ; pour retirer l'ombre, décochez Barres d'expérience et de réputation ombrées sous Barre classique."
L["WN18_8_TITLE"] = "Corrections"
L["WN18_8_TEXT"] = "Former fonctionne pour les recettes loin dans la liste d'un maître. Les boutons de discussion restent sur chaque onglet, et Maj-clic lie un talent dans la discussion. La carte du monde ouverte en combat n'intercepte plus les clics, et les boutons rouges du mode Édition restent entiers quand vous changez de thème."
L["WN17_1_TITLE"] = "Erreurs des barres de nom"
L["WN17_1_TEXT"] = "Avec un thème actif, les barres de nom classiques ne provoquent plus de messages d'erreur."
L["WN17_2_TITLE"] = "Améliorations de la cible"
L["WN17_2_TEXT"] = "Les améliorations sous les cadres de la cible et du focus apparaissent désormais à leur place quand vous changez de cible, sans le petit saut."
L["WN17_3_TITLE"] = "Carte du monde en combat"
L["WN17_3_TEXT"] = "La carte du monde classique ouverte en combat a désormais le même aspect que hors combat."
L["WN16_1_TITLE"] = "Icônes d'action"
L["WN16_1_TEXT"] = "Avec un thème actif, les icônes des boutons d'action ne s'assombrissent plus au hasard."
L["WN16_2_TITLE"] = "Lueur de combat"
L["WN16_2_TEXT"] = "Avec Barres de vie épaisses sur le nom, la lueur rouge de combat et la lueur dorée de repos entourent désormais tout le cadre du joueur au lieu de la barre de vie. Les Barres de vie épaisses sont désactivées par défaut ; activez-les dans les options (/fcui), sous Cadres d'unité."
L["WN16_3_TITLE"] = "Barres de nom"
L["WN16_3_TEXT"] = "Avec les barres de nom classiques désactivées, les barres de nom du jeu ne provoquent plus de messages d'erreur."
L["WN15_1_TITLE"] = "Menace"
L["WN15_1_TEXT"] = "Le pourcentage de menace de Classic Era s'affiche désormais au-dessus des cadres de la cible et du focus en combat. La lueur rouge autour des cadres d'unité est désormais masquée par défaut ; pour la retrouver, décochez Masquer la lueur de menace dans les options (/fcui), sous Cadres d'unité."
L["WN15_2_TITLE"] = "Mana du druide"
L["WN15_2_TEXT"] = "En forme d'ours et de félin, les druides voient désormais leur mana dans une petite barre sous la barre de rage ou d'énergie."
L["WN15_3_TITLE"] = "Couleur de vie ennemie"
L["WN15_3_TEXT"] = "Désactivé par défaut. Pour l'utiliser, activez Barres de vie épaisses dans les options (/fcui), sous Cadres d'unité, puis choisissez Selon la réaction sous Vie des ennemis : les ennemis neutres ont une barre jaune, les hostiles une barre rouge."
L["WN15_4_TITLE"] = "Texte en anglais"
L["WN15_4_TEXT"] = "Pour un jeu dans une autre langue : les textes propres à cet addon peuvent s'afficher en anglais, partie par partie. Désactivé par défaut ; activez-le dans les options (/fcui), sous Autre, Texte en anglais."
L["WN15_5_TITLE"] = "Liste Qui"
L["WN15_5_TEXT"] = "La flèche en haut de la dernière colonne de la Liste Qui contient désormais les filtres de classe, de race et de zone du jeu. Une recherche avec un ou deux résultats reste dans la fenêtre au lieu d'aller dans la discussion."
L["WN15_6_TITLE"] = "Couleur unie"
L["WN15_6_TEXT"] = "Couleur unie peint les décors des fenêtres et des barres d'une seule couleur pleine au lieu du métal. Elle garde désormais les fines lignes à l'intérieur des fenêtres, autour des listes, des pieds et des séparateurs, sauf si vous activez aussi Masquer les bordures internes. Les deux sont désactivés par défaut : activez Thème personnalisé, puis Couleur unie, dans les options (/fcui), sous Apparence."
L["WN15_7_TITLE"] = "Minuteurs d'attaque"
L["WN15_7_TEXT"] = "Les minuteurs d'attaque peuvent désormais tourner sans l'éclair après chaque coup : décochez Éclair à chaque coup dans les options (/fcui), sous Minuteurs d'attaque."
L["WN15_8_TITLE"] = "Barres de nom"
L["WN15_8_TEXT"] = "Les noms et petits nombres des barres de nom utilisent désormais le texte simple de Classic Era. Nouveau et désactivé par défaut : Même taille de près et de loin garde toutes les barres de nom à la même taille, comme dans Classic Era ; activez-le dans les options (/fcui), sous Barres de nom."
L["WN15_9_TITLE"] = "Fenêtres"
L["WN15_9_TEXT"] = "Les fenêtres de quête, de dialogue et de marchand et la liste du journal de quêtes ont désormais la fine bordure de Classic Era autour de leur contenu, et la fenêtre du personnage montre le visage de votre personnage sur chaque onglet."
L["WN15_10_TITLE"] = "Corrections"
L["WN15_10_TEXT"] = "Avec un thème actif, les bords d'icônes, les anneaux de portrait, les menus et les flèches de page du marchand prennent sa couleur, et les curseurs restent visibles. Les onglets de la fenêtre du personnage réagissent désormais là où ils sont dessinés."
L["WN14_1_TITLE"] = "Manette"
L["WN14_1_TEXT"] = "Avec l'interface manette active, le grimoire classique, les talents et le journal de quêtes s'ouvrent dans les fenêtres du jeu lui-même, pour qu'une manette puisse s'y déplacer."
L["WN14_2_TITLE"] = "Thème partout"
L["WN14_2_TEXT"] = "Avec un thème actif, les pièces du jeu lui-même prennent aussi sa couleur là où les classiques sont décochées : minicarte, cadres d'unité, barres, fenêtres et boutons du menu du jeu."
L["WN14_3_TITLE"] = "Obscurité"
L["WN14_3_TEXT"] = "Sombre a un curseur du gris clair au noir, avec un bouton pour revenir à la valeur par défaut."
L["WN14_4_TITLE"] = "Couleur unie"
L["WN14_4_TEXT"] = "Couleur unie (Thème personnalisé) affiche les parties cochées dans une seule couleur unie, dans les mêmes formes."
L["WN14_5_TITLE"] = "Micro-boutons"
L["WN14_5_TEXT"] = "Masquer des micro-boutons fonctionne désormais sur le micro-menu du jeu lui-même quand la barre classique est désactivée, et peut masquer la boutique."
L["WN14_6_TITLE"] = "Barres 6 à 8"
L["WN14_6_TEXT"] = "Masquer les barres 6 à 8 a disparu : les réglages des barres d'action du jeu décident."
L["WN14_7_TITLE"] = "Corrections"
L["WN14_7_TEXT"] = "Coordonnées : masquées et au survol fonctionnent avec la minicarte du jeu, les boutons de minicarte des autres add-ons prennent le thème, et le sac à dos d'un chasseur affiche les emplacements libres au lieu des munitions."
L["WN13_1_TITLE"] = "Lueur de menace"
L["WN13_1_TEXT"] = "Masquer la lueur de menace (Cadres d'unité) retire la lueur rouge de menace des cadres d'unité. Le nombre de menace du jeu reste."
L["WN13_2_TITLE"] = "Objets de quête"
L["WN13_2_TEXT"] = "Objets de quête sobres (Fenêtres de sac) affiche les objets de quête des sacs et de la banque sans le cadre de quête."
L["WN13_3_TITLE"] = "Nombres"
L["WN13_3_TEXT"] = "Nombres sans séparateurs (Cadres d'unité) retire les séparateurs de milliers des grands nombres, sur les barres et dans tout le jeu."
L["WN13_4_TITLE"] = "Icônes d'action"
L["WN13_4_TEXT"] = "Avec un thème, les icônes d'action s'affichent de nouveau entières, comme dans Classic Era ; seule leur propre bordure prend la couleur du thème."
L["WN13_5_TITLE"] = "Vos barres"
L["WN13_5_TEXT"] = "Si la 0.14.0 a changé vos barres, une ligne de discussion à la connexion vous permet de les remettre comme avant ou de prendre l'aspect classique."
L["WN13_6_TITLE"] = "Fenêtre sociale"
L["WN13_6_TEXT"] = "Les onglets Amis et Raid ont leur fin cadre comme dans Classic Era, et la description de l'onglet Raid s'affiche de nouveau hors d'un raid."
L["WN13_7_TITLE"] = "Corrections"
L["WN13_7_TEXT"] = "Le butin sous la souris s'ouvre avec le premier objet sous le curseur, les libellés des onglets passent au blanc au survol, et Disposition classique rétablit le micro-menu et les emplacements de sac classiques."
L["WN12_1_TITLE"] = "Fenêtres"
L["WN12_1_TEXT"] = "Un verrou et une réinitialisation se trouvent à côté du bouton de fermeture de chaque fenêtre : déverrouillée, la fenêtre se déplace par son titre. Les fenêtres de quête et de dialogue, la fenêtre sociale, la recherche de groupe et le livre des métiers se placent et se dimensionnent dans Fenêtres ClassicUI Forever."
L["WN12_2_TITLE"] = "Minuteurs d'attaque"
L["WN12_2_TEXT"] = "Les minuteurs d'attaque du jeu à l'aspect de la barre d'incantation 1.x, avec une couleur par main et un éclat à chaque coup. Les couleurs et l'Épaisseur de la bordure se règlent dans les options."
L["WN12_3_TITLE"] = "Barres de vie épaisses"
L["WN12_3_TEXT"] = "Une barre de vie plus haute sur les cadres du joueur, de la cible et du focus, sur le nom ou sur le mana (Cadres d'unité). Case du nom aux couleurs de classe et Taille des noms y sont aussi nouveaux."
L["WN12_4_TITLE"] = "Griffons"
L["WN12_4_TEXT"] = "Les griffons se déplacent, se dimensionnent ou se masquent dans le mode Édition du jeu. Avec l'aimantation activée, ils s'alignent sur les barres et reviennent à leur place."
L["WN12_5_TITLE"] = "Compteur de dégâts"
L["WN12_5_TEXT"] = "Le compteur de dégâts dans le cadre 1.x, avec des boutons classiques et un fond de marbre ou d'arbre de talents que l'on peut déplacer."
L["WN12_6_TITLE"] = "Langues"
L["WN12_6_TEXT"] = "ClassicUI Forever existe désormais en allemand, français, espagnol et italien."
L["WN12_7_TITLE"] = "Options"
L["WN12_7_TEXT"] = "Nouveaux onglets FAQ et Soutien, une Couleur personnalisée pour le thème et une recherche qui trouve un réglage sous plus de noms."
L["WN12_8_TITLE"] = "Ressources"
L["WN12_8_TEXT"] = "L'affichage personnel des ressources en barres 1.x dans l'ancienne bordure de plaque de nom, avec le réglage Écart des barres."
L["WN12_9_TITLE"] = "Barre classique"
L["WN12_9_TEXT"] = "Emplacements de sac à la taille classique, chaque micro-bouton peut être masqué, le bouton d'aide revient au bout du micro-menu, et Le bandeau porte les barres 2 et 3 garde ces barres sur le bandeau."
L["WN12_10_TITLE"] = "Minicarte et discussion"
L["WN12_10_TEXT"] = "Des coordonnées ainsi qu'une bordure et un en-tête masquables sur la minicarte, l'œil de la recherche de groupe dessus quand son micro-bouton est masqué, et chaque bouton de discussion se masque séparément."
L["WN12_11_TITLE"] = "Corrections"
L["WN12_11_TEXT"] = "Les barres ne sautent plus en haut de l'écran après un déplacement en mode Édition, la barre 1 se déplace avec les flèches en mode Édition, la barre d'expérience n'apparaît plus en double après une connexion en combat, et les pages de butin ne répètent plus d'objets."
L["WN12_12_TITLE"] = "Petites corrections"
L["WN12_12_TEXT"] = "Les nombres du familier et du groupe tiennent dans leurs barres, le micro-menu ne saute plus quand on le déplace, la barre de latence garde son cadre, et les infobulles des micro-boutons s'affichent une fois avec la bonne limite de quêtes."
L["WN11_1_TITLE"] = "Discussion"
L["WN11_1_TEXT"] = "Masquer les boutons de discussion permet à la discussion de se coller au bord de l'écran, et Barre de défilement de la discussion garde celle de WoW Forever (Boutons de discussion)."
L["WN11_2_TITLE"] = "Niveaux des quêtes"
L["WN11_2_TEXT"] = "Niveaux des quêtes (Quêtes) affiche le niveau de chaque quête sur la carte, dans le suivi et dans le journal de quêtes, en phase avec le filtre de la carte."
L["WN11_3_TITLE"] = "Thème sombre"
L["WN11_3_TEXT"] = "Les menus du clic droit, les boutons de minicarte des addons, les boutons de zoom, l'horloge et l'icône jour et nuit prennent le thème, et les icônes d'action n'ont plus de bord clair."
L["WN11_4_TITLE"] = "Corrections"
L["WN11_4_TEXT"] = "Plus de double niveau de quête dans le suivi, plus d'erreurs des menus du clic droit en donjon, et le menu de la cible reste à l'écran."
L["WN10_1_TITLE"] = "Minicarte"
L["WN10_1_TEXT"] = "Chaque élément de la minicarte peut s'afficher, s'afficher seulement au survol ou être masqué (Minicarte dans les options), et le zoom avant et arrière se déplacent chacun autour de l'anneau dans les fenêtres ClassicUI Forever."
L["WN10_2_TITLE"] = "Micro-menu"
L["WN10_2_TEXT"] = "Les descriptions de Classic Era dans les infobulles des micro-boutons, et Masquer des micro-boutons retire des boutons un par un du menu (Barre classique)."
L["WN10_3_TITLE"] = "Trousseau"
L["WN10_3_TEXT"] = "S'ouvre même sans clés, dans sa propre fenêtre, avec les graphismes de Classic Era."
L["WN10_4_TITLE"] = "Nouvelles options"
L["WN10_4_TEXT"] = "Masquer la barre de posture (Barre classique), Taille du texte du nom (Barres de nom) et Infobulle d'unité sur les barres (Cadres d'unité)."
L["WN10_5_TITLE"] = "Corrections"
L["WN10_5_TEXT"] = "Les flèches de défilement grisent quand il n'y a rien à faire défiler, le journal de quêtes surligne comme dans Classic Era, Dernière connexion de la guilde trie correctement et la fenêtre des macros s'ouvre à côté du grimoire."
L["WN10_6_TITLE"] = "Petites corrections"
L["WN10_6_TEXT"] = "Les flèches des talents, l'onglet de guilde sans guilde, les flèches de page au-dessus de la carte, le sac des boutons d'addons et des invites de disposition plus courtes."
L["WN9_1_TITLE"] = "Carte du monde classique"
L["WN9_1_TEXT"] = "La petite carte de Classic Era, avec la liste de quêtes de la carte dans son propre volet à côté et les récompenses après le texte de la quête. Barre de navigation de la carte sous Carte dans les options ramène la disposition de carte du jeu."
L["WN9_2_TITLE"] = "Nouvelles options"
L["WN9_2_TEXT"] = "Masquer le bouton de quêtes de la carte (Carte), Barres à la taille classique (Barre classique) et Secousse à l'interruption (Barres d'incantation)."
L["WN9_3_TITLE"] = "Style classique"
L["WN9_3_TEXT"] = "Les menus du clic droit, les listes déroulantes, la fenêtre sociale, la recherche de groupe, la liste Qui et la liste de guilde suivent Classic Era ; la fenêtre des options prend l'apparence du client Classic Era actuel, et la liste d'ignorés et la cabine d'essayage le style classique."
L["WN9_4_TITLE"] = "Mode Édition"
L["WN9_4_TEXT"] = "Le grimoire peut être déplacé et redimensionné dans les fenêtres ClassicUI Forever."
L["WN9_5_TITLE"] = "Barres et suivi"
L["WN9_5_TEXT"] = "Les barres 4 et 5 gardent leur place au bord de l'écran, et le suivi des quêtes ne les recouvre plus."
L["WN9_6_TITLE"] = "Corrections"
L["WN9_6_TEXT"] = "Les PNJ neutres affichent leur niveau au lieu d'un crâne, et cliquer sur les barres d'un cadre d'unité cible de nouveau."
L["WN9_7_TITLE"] = "Fenêtres et onglets"
L["WN9_7_TEXT"] = "Les fenêtres de marchand, de courrier, de charte de guilde et de tabard, et beaucoup d'autres fenêtres et onglets, s'alignent sur Classic Era ; Échap ferme la fenêtre de charte de guilde."
L["WN8_1_TITLE"] = "Griffons devant les barres"
L["WN8_1_TEXT"] = "Cochez Griffons devant les barres sous Barre classique dans les options pour dessiner les griffons devant les barres 2 et 3."
L["WN8_2_TITLE"] = "Fenêtres ouvertes à l'appui"
L["WN8_2_TEXT"] = "Les touches du grimoire, des métiers, des talents, de la guilde et du journal de quêtes ainsi qu'Échap agissent à l'appui, comme les fenêtres du jeu."
L["WN8_3_TITLE"] = "Corrections"
L["WN8_3_TEXT"] = "Les sorts se glissent de nouveau sur la barre d'action 1, le nom de la zone est centré sur la barre de la minicarte où que soit le calendrier, et les onglets et commandes de familier du grimoire s'affichent correctement."
L["WN7_1_TITLE"] = "Texte des touches classique"
L["WN7_1_TEXT"] = "Les noms de touche sur les boutons d'action ont la taille et le contour de Classic Era. Taille du texte des touches sous Style des boutons dans les options les agrandit ou les réduit."
L["WN7_2_TITLE"] = "Places du calendrier"
L["WN7_2_TEXT"] = "Le calendrier est un petit carré près du nom de la zone ; placez-le sur l'anneau ou derrière l'icône jour et nuit sous Bouton du calendrier dans les options. Cochez Calendrier sous Minicarte dans les fenêtres ClassicUI Forever en mode Édition pour le déplacer ou le redimensionner."
L["WN6_1_TITLE"] = "Bouton du calendrier"
L["WN6_1_TEXT"] = "Le calendrier se trouve sous l'icône jour et nuit sur la minicarte. Pour le masquer, décochez Bouton du calendrier sous Minicarte dans les options."
L["WN5_1_TITLE"] = "Corrections"
L["WN5_1_TEXT"] = "Le repère nouveaux joueurs bienvenus de la recherche de groupe s'aligne sur les icônes de rôle. Détails dans le journal complet des modifications."
L["WN4_1_TITLE"] = "Corrections"
L["WN4_1_TEXT"] = "Les onglets prennent la souris sur l'onglet lui-même, un métier lancé depuis le grimoire ferme le livre en combat, et l'en-tête de la fenêtre de butin est propre. Détails dans le journal complet des modifications."
L["WN3_1_TITLE"] = "Éléments de la barre classique"
L["WN3_1_TEXT"] = "Classic n'avait ni bouton des métiers ni sac de composants, donc le bouton des métiers quitte le micro-menu (les métiers s'ouvrent depuis le grimoire) et le sac de composants est un petit bouton rond au survol. Les barres 2 et 3 tiennent de nouveau entre les griffons. Les deux sont des lignes sous Barre classique dans les options."
L["WN2_1_TITLE"] = "Mode Édition des fenêtres"
L["WN2_1_TEXT"] = "Cochez Fenêtres en mode Édition pour déplacer et redimensionner la fiche de personnage, le grimoire, les talents, le journal de quêtes, les métiers et la carte."
L["WN2_2_TITLE"] = "Profils"
L["WN2_2_TEXT"] = "Un onglet Profils dans les options garde des réglages nommés par personnage."
L["WN2_3_TITLE"] = "Bronze ou Sombre"
L["WN2_3_TEXT"] = "Le thème personnalisé existe dans le bronze de Forever ou dans un anthracite sombre. Voir l'option Thème personnalisé."
L["WN2_4_TITLE"] = "Barre classique"
L["WN2_4_TEXT"] = "Les barres ne sont plus réduites par défaut. La barre porte maintenant la barre de latence, le trousseau et le sac de composants comme en classique ; chacun peut être déplacé en mode Édition ou masqué sous Barre classique dans les options."
L["WN2_5_TITLE"] = "Boutons de la minicarte"
L["WN2_5_TEXT"] = "Les boutons de minicarte des autres addons peuvent se regrouper derrière un bouton sur l'anneau. Voir l'option Regrouper les boutons d'addons."
L["WN2_6_TITLE"] = "Options"
L["WN2_6_TEXT"] = "Des sections Quêtes et Carte, et de nouvelles lignes pour le cadre de la carte, la fenêtre de butin, les jets de butin, masquer le suivi du jeu, le bouton des métiers et le texte des touches."
L["WN2_7_TITLE"] = "Réinitialiser la disposition classique"
L["WN2_7_TEXT"] = "Remet d'un coup les fenêtres, le suivi, les griffons, les éléments de barre et les réglages de disposition."
